// enc_iface.h: the NVENC class interface used by the H.264 / HEVC path.
#pragma once
#include "clc7b7.h"
#include "clc9b7.h"
#include "nvmisc.h"

// These assertions cover only methods and fields shared by the H.264 / HEVC
// submission path in enc.c. C7B7 and C9B7 are not interchangeable in general:
// AV1 / VP9 methods and some semaphore fields differ.
#define NVENC_ASSERT_SHARED_METHOD(name) \
    _Static_assert(NVC7B7_##name == NVC9B7_##name, #name " differs between C7B7 and C9B7")
#define NVENC_ASSERT_SHARED_ENUM(name) \
    _Static_assert(NVC7B7_##name == NVC9B7_##name, #name " differs between C7B7 and C9B7")
#define NVENC_ASSERT_SHARED_FIELD(name) \
    _Static_assert(DRF_SHIFTMASK(NVC7B7_##name) == DRF_SHIFTMASK(NVC9B7_##name), \
                   #name " differs between C7B7 and C9B7")

NVENC_ASSERT_SHARED_METHOD(SET_APPLICATION_ID);
NVENC_ASSERT_SHARED_METHOD(SET_CONTROL_PARAMS);
NVENC_ASSERT_SHARED_METHOD(SET_PICTURE_INDEX);
NVENC_ASSERT_SHARED_METHOD(SET_IN_DRV_PIC_SETUP);
NVENC_ASSERT_SHARED_METHOD(SET_IOHISTORY);
NVENC_ASSERT_SHARED_METHOD(SET_IN_MEPRED_DATA);
NVENC_ASSERT_SHARED_METHOD(SET_OUT_MEPRED_DATA);
NVENC_ASSERT_SHARED_METHOD(SET_OUT_REF_PIC_LUMA);
NVENC_ASSERT_SHARED_METHOD(SET_OUT_REF_PIC_CHROMA);
NVENC_ASSERT_SHARED_METHOD(SET_OUT_ENC_STATUS);
NVENC_ASSERT_SHARED_METHOD(SET_OUT_BITSTREAM);
NVENC_ASSERT_SHARED_METHOD(SET_IN_CUR_PIC);
NVENC_ASSERT_SHARED_METHOD(SET_IN_CUR_PIC_CHROMA_U);
NVENC_ASSERT_SHARED_METHOD(SET_IN_CUR_PIC_CHROMA_V);
NVENC_ASSERT_SHARED_METHOD(SET_IO_RC_PROCESS);
NVENC_ASSERT_SHARED_METHOD(SET_IN_RCDATA);
NVENC_ASSERT_SHARED_METHOD(SET_OUT_COLOC_DATA);
NVENC_ASSERT_SHARED_METHOD(SET_IN_COLOC_DATA);
NVENC_ASSERT_SHARED_METHOD(SET_IN_REF_PIC0_LUMA);
NVENC_ASSERT_SHARED_METHOD(SET_IN_REF_PIC0_CHROMA);
NVENC_ASSERT_SHARED_METHOD(SET_IN_REF_PIC1_LUMA);
NVENC_ASSERT_SHARED_METHOD(SET_IN_REF_PIC1_CHROMA);
NVENC_ASSERT_SHARED_METHOD(SET_IN_REF_PIC2_LUMA);
NVENC_ASSERT_SHARED_METHOD(SET_IN_REF_PIC2_CHROMA);
NVENC_ASSERT_SHARED_METHOD(SET_IN_REF_PIC3_LUMA);
NVENC_ASSERT_SHARED_METHOD(SET_IN_REF_PIC3_CHROMA);
NVENC_ASSERT_SHARED_METHOD(EXECUTE);
NVENC_ASSERT_SHARED_METHOD(SEMAPHORE_A);
NVENC_ASSERT_SHARED_METHOD(SEMAPHORE_D);

NVENC_ASSERT_SHARED_ENUM(SET_APPLICATION_ID_ID_NVENC_H264);
NVENC_ASSERT_SHARED_ENUM(SET_APPLICATION_ID_ID_NVENC_H265);
NVENC_ASSERT_SHARED_FIELD(SET_CONTROL_PARAMS_CODEC_TYPE);
NVENC_ASSERT_SHARED_ENUM(SET_CONTROL_PARAMS_CODEC_TYPE_H264);
NVENC_ASSERT_SHARED_FIELD(SET_CONTROL_PARAMS_FORCE_OUT_PIC);
NVENC_ASSERT_SHARED_FIELD(SET_CONTROL_PARAMS_RCMODE);
NVENC_ASSERT_SHARED_FIELD(SET_CONTROL_PARAMS_RCSTAT_WRITE);
NVENC_ASSERT_SHARED_FIELD(SET_CONTROL_PARAMS_RCSTAT_READ);
NVENC_ASSERT_SHARED_FIELD(SEMAPHORE_D_STRUCTURE_SIZE);
NVENC_ASSERT_SHARED_ENUM(SEMAPHORE_D_STRUCTURE_SIZE_ONE);
NVENC_ASSERT_SHARED_FIELD(SEMAPHORE_D_OPERATION);
NVENC_ASSERT_SHARED_ENUM(SEMAPHORE_D_OPERATION_RELEASE);
NVENC_ASSERT_SHARED_ENUM(SEMAPHORE_D_PAYLOAD_SIZE_32BIT);

#undef NVENC_ASSERT_SHARED_METHOD
#undef NVENC_ASSERT_SHARED_ENUM
#undef NVENC_ASSERT_SHARED_FIELD

static inline NvU32 nvenc_pic_setup_magic(NvU32 cls, NvU32 fallback)
{
    switch (cls) {
        case NVC7B7_VIDEO_ENCODER: return 0xc7b70006u; // NVENC 7.3 (GA10x)
        case NVC9B7_VIDEO_ENCODER: return 0xc9b70006u; // NVENC 8.2 (Ada)
        default: return cls ? (cls << 16) | 0x0006u : fallback;
    }
}

static inline NvU32 nvenc_semaphore32_word(NvU32 cls)
{
    if (cls == NVC7B7_VIDEO_ENCODER) {
        return DRF_DEF(C7B7, _SEMAPHORE_D, _STRUCTURE_SIZE, _ONE) |
               DRF_DEF(C7B7, _SEMAPHORE_D, _OPERATION, _RELEASE) |
               DRF_DEF(C7B7, _SEMAPHORE_D, _PAYLOAD_SIZE, _32BIT);
    }

    // Keep the existing C9B7-derived word for Ada, TU117, and the legacy
    // fallback path. For the 32-bit payload both classes encode the same word.
    return DRF_DEF(C9B7, _SEMAPHORE_D, _STRUCTURE_SIZE, _ONE) |
           DRF_DEF(C9B7, _SEMAPHORE_D, _OPERATION, _RELEASE) |
           DRF_DEF(C9B7, _SEMAPHORE_D, _PAYLOAD_SIZE, _32BIT);
}
